<script lang="ts">
  import { ArrowLeft, ArrowRight, Check, Clock3, MapPin, Users } from '@lucide/svelte';
  import { onMount } from 'svelte';
  import type { PageData } from './$types';
  export let data: PageData;
  let message = '', pending = false, notice = '', error = '';
  onMount(() => document.querySelector('.project-detail-page')?.setAttribute('data-app-ready', 'true'));
  async function apply() {
    pending = true; notice = ''; error = '';
    const response = await fetch(`/api/projects/${data.project.id}/apply`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ message }) });
    const payload = await response.json();
    if (!response.ok) error = payload.message ?? 'Could not send your application.';
    else notice = payload.message;
    pending = false;
  }
  async function accept(applicationId: string) {
    const response = await fetch(`/api/projects/${data.project.id}/applications/${applicationId}/accept`, { method: 'POST' });
    const payload = await response.json();
    if (!response.ok) { error = payload.message ?? 'Could not accept applicant.'; return; }
    window.location.reload();
  }
  async function reject(applicationId: string) {
    const response = await fetch(`/api/projects/${data.project.id}/applications/${applicationId}/reject`, { method: 'POST' });
    const payload = await response.json();
    if (!response.ok) { error = payload.message ?? 'Could not reject applicant.'; return; }
    window.location.reload();
  }
</script>

<svelte:head><title>{data.project.title} — BuildTogether</title></svelte:head>
<div class="project-detail-page"><header class="detail-header"><a class="brand" href="/home" aria-label="BuildTogether home"><span class="brand-mark brand-image"><img src="/brand/handshake-emblem.png" alt="" /></span><span>Build<span>Together</span></span></a><a class="back-link" href="/home"><ArrowLeft size={15} /> Back to home</a></header><main class="detail-main"><a class="back-text" href="/home"><ArrowLeft size={14} /> All projects</a><div class="detail-layout"><article class="detail-card"><span class="status">{data.project.status}</span><p class="eyebrow">{data.project.category} · {data.project.department}</p><h1>{data.project.title}</h1><p class="summary">{data.project.summary}</p><div class="meta"><span><Clock3 size={15} /> {data.project.hoursPerWeek}</span><span><MapPin size={15} /> {data.project.location}</span><span><Users size={15} /> {data.currentMembers} of {data.project.teamSize ?? data.project.openRoles + 1} people</span></div><div class="detail-divider"></div><h2>What this project needs</h2>{#if data.project.roles && data.project.roles.length > 0}<div class="roles">{#each data.project.roles as role}<section><div><h3>{role.title} <small>{role.peopleNeeded} needed</small></h3><p>{role.description}</p><div class="tags">{#each role.skills as skill}<span>{skill}</span>{/each}</div></div></section>{/each}</div>{:else}<div class="tags">{#each data.project.skills as skill}<span>{skill}</span>{/each}</div>{/if}</article><aside class="side-card"><p class="eyebrow">Created by</p><h2>{data.project.creator}</h2>{#if data.isCreator}<a class="edit-link" href={`/projects/${data.project.id}/edit`}>Edit project <ArrowRight size={13} /></a>{/if}{#if data.isCreator}<p class="side-copy">Review students who want to join your project.</p>{#if data.applications.length > 0}<div class="applications">{#each data.applications as application}<div class="application"><strong>{application.applicant?.firstName} {application.applicant?.lastName}</strong><p>{application.message || 'No message included.'}</p><div class="review-actions"><button class="button button-dark button-small" type="button" onclick={() => accept(application.id)}>Accept <Check size={13} /></button><button class="button button-outline button-small" type="button" onclick={() => reject(application.id)}>Reject</button></div></div>{/each}</div>{:else}<p class="side-copy">No pending applications yet.</p>{/if}{:else}{#if data.currentApplication === 'accepted'}<div class="notice"><Check size={15} /> You are on this team.</div>{:else if data.currentApplication === 'pending'}<div class="notice">Your application is pending.</div>{:else if data.currentMembers >= (data.project.teamSize ?? data.project.openRoles + 1)}<div class="notice">This team is full.</div>{:else}<p class="side-copy">Interested in contributing? Tell the creator why you would be a good fit.</p><form onsubmit={(event) => { event.preventDefault(); apply(); }}><textarea aria-label="Application message" bind:value={message} rows="5" placeholder="How could you contribute?"></textarea>{#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}<button class="button button-dark button-full" type="submit" disabled={pending}>{pending ? 'Sending…' : 'Request to join'} <ArrowRight size={15} /></button></form>{/if}{/if}</aside></div></main></div>

<style>
  .project-detail-page{min-height:100vh;background:#f6fbff;color:#000;font-family:var(--byui-body)}.detail-header{height:78px;padding:0 clamp(20px,6vw,80px);display:flex;justify-content:space-between;align-items:center;background:#fff;border-bottom:1px solid rgba(148,149,152,.3)}.detail-header .brand{text-decoration:none}.detail-header .brand-image{width:46px;height:31px}.back-link,.back-text{display:flex;align-items:center;gap:7px;color:var(--byui-deep-blue);font:700 12px var(--byui-display);text-decoration:none}.detail-main{max-width:1100px;margin:auto;padding:50px 20px 90px}.back-text{margin-bottom:20px}.detail-layout{display:grid;grid-template-columns:1fr 320px;gap:16px}.detail-card,.side-card{background:#fff;border:1px solid #dce7e9;border-radius:11px;padding:30px}.status{display:inline-block;color:#2d8b68;background:#dff1e8;border-radius:99px;padding:5px 8px;font-size:8px;font-weight:800;letter-spacing:.08em}.eyebrow{color:var(--byui-blue);font:800 10px var(--byui-display);text-transform:uppercase;letter-spacing:.14em;margin:18px 0 10px}.detail-card h1{font:700 clamp(40px,6vw,70px)/.95 var(--byui-display);letter-spacing:-.06em;margin:0;color:#000}.summary{color:#53656b;font-size:15px;line-height:1.7;max-width:680px;margin:20px 0}.meta{display:flex;flex-wrap:wrap;gap:15px;color:#6f8288;font-size:11px}.meta span{display:flex;align-items:center;gap:5px}.detail-divider{border-top:1px solid #dfe6e8;margin:30px 0}.detail-card h2,.side-card h2{font:700 24px var(--byui-display);margin:0;color:var(--byui-deep-blue)}.roles{display:grid;gap:10px;margin-top:18px}.roles section{border:1px solid #e0e9eb;border-radius:8px;padding:15px}.roles h3{font:700 15px var(--byui-display);margin:0;color:var(--byui-deep-blue)}.roles h3 small{font:400 10px var(--byui-body);color:#77898e;margin-left:7px}.roles p,.side-copy{color:#687b80;font-size:12px;line-height:1.6;margin:8px 0}.tags{display:flex;flex-wrap:wrap;gap:6px;margin-top:12px}.tags span{background:#e8f4fb;color:var(--byui-deep-blue);border-radius:4px;padding:6px 8px;font:700 10px var(--byui-display)}.side-card{height:max-content}.side-card h2{font-size:27px}.edit-link{display:inline-flex;align-items:center;gap:5px;color:var(--byui-blue);font:700 10px var(--byui-display);text-decoration:none;margin-top:12px}.applications{display:grid;gap:10px;margin-top:20px}.application{border-top:1px solid #e1e9eb;padding-top:12px}.application strong{color:var(--byui-deep-blue);font:700 13px var(--byui-display)}.application p{color:#687b80;font-size:11px;line-height:1.5}.review-actions{display:flex;gap:7px;flex-wrap:wrap}.side-card textarea{box-sizing:border-box;width:100%;resize:vertical;border:1px solid #c9d8df;border-radius:6px;padding:10px;font:13px var(--byui-body);outline:0}.side-card textarea:focus{border-color:var(--byui-blue)}.button-full{width:100%;justify-content:center}.notice{display:flex;align-items:center;gap:7px;background:var(--byui-light-blue);color:var(--byui-deep-blue);border-radius:6px;padding:11px;font:700 11px var(--byui-display);margin-top:18px}.form-error{color:#a32626;font:11px var(--byui-display)}@media(max-width:760px){.detail-layout{grid-template-columns:1fr}.detail-header{padding:0 20px}.detail-header .back-link{display:none}}
</style>
